    let savedLanguage='bn';try{savedLanguage=localStorage.getItem('nur-site-language')||'bn';}catch(error){}setLanguage(savedLanguage);
    const leadForm=document.getElementById('leadForm');
    leadForm.addEventListener('submit',async(event)=>{event.preventDefault();const status=document.getElementById('leadFormStatus');const language=document.documentElement.lang;const config=window.SUPABASE_CONFIG||{};if(!config.url||!config.anonKey){status.textContent=language==='bn'?'ফর্মটি এখনো সেটআপ করা হয়নি। WhatsApp-এ যোগাযোগ করুন।':'The inquiry form is not set up yet. Please use WhatsApp.';return}const formData=new FormData(leadForm);const payload=Object.fromEntries(formData.entries());payload.privacy_consent=formData.get('privacy_consent')==='on';const button=leadForm.querySelector('button[type="submit"]');button.disabled=true;status.textContent=language==='bn'?'পাঠানো হচ্ছে…':'Sending…';try{const response=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'submission_failed');leadForm.reset();status.textContent=language==='bn'?'ধন্যবাদ! আপনার বার্তা পাঠানো হয়েছে।':'Thank you! Your inquiry has been sent.'}catch(error){status.textContent=language==='bn'?'বার্তা পাঠানো যায়নি। অনুগ্রহ করে WhatsApp-এ যোগাযোগ করুন।':'Could not send your inquiry. Please contact me on WhatsApp.'}finally{button.disabled=false}});
    toggle.addEventListener('click',()=>{const open=links.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');});
    links.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{links.classList.remove('open');toggle.setAttribute('aria-expanded','false');}));
  </script>
</body>
</html>
